"""Normalize a callisto JSON document: drop digests, fingerprints and commit SHAs so plans can be compared."""
import json
import re
import sys

DROP = {"digest", "fingerprint", "sha", "intentDigest", "orchestrationRevision", "releaseSourceRevision"}


def walk(value):
    if isinstance(value, dict):
        return {k: walk(v) for k, v in value.items() if k not in DROP}
    if isinstance(value, list):
        return [walk(v) for v in value]
    if isinstance(value, str):
        return re.sub(r"[0-9a-f]{40,64}", "<hex>", value)
    return value


text = open(sys.argv[1]).read()
start = text.find("{")
print(json.dumps(walk(json.loads(text[start:])), indent=1, sort_keys=True))

