        args.source_root.as_deref(),
        global,
        |intent| callisto_model::npm_publishes(intent).is_empty(),
        |capability| capability.pack_npm_tarballs(&outdir),
    )?;
    match global.format {
        OutputFormat::Json => emit_report(
            &mut std::io::stdout(),
            &callisto_model::ReleasePackNpmReport { built },
            global.dry_run,
        )?,
        OutputFormat::Text => emit_line(&format!(
            "Packed npm packages {} into {}",
            built.join(", "),
            outdir.display()
        ))?,
    }
    Ok(ExitCode::SUCCESS)
}

fn package_cargo(args: ReleasePackageCargoArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    refuse_dry_run("release package-cargo", global)?;
    let built = build_from_intent(
        "Cargo",
        &args.intent,
        args.source_root.as_deref(),
        global,
        |intent| callisto_model::cargo_publishes(intent).is_empty(),
        |capability| capability.package_cargo_crates(),
    )?;
    match global.format {
        OutputFormat::Json => emit_report(
            &mut std::io::stdout(),
            &callisto_model::ReleasePackageCargoReport { built },
            global.dry_run,
        )?,
        OutputFormat::Text => emit_line(&format!("Packaged crates {}", built.join(", ")))?,
    }
    Ok(ExitCode::SUCCESS)
}

